/* ==UserStyle==
@name Mullvad Leta Catppuccin
@namespace github.com/catppuccin/userstyles/styles/mullvad-leta
@homepageURL https://github.com/catppuccin/userstyles/tree/main/styles/mullvad-leta
@version 2025.09.06
@updateURL https://github.com/catppuccin/userstyles/raw/main/styles/mullvad-leta/catppuccin.user.less
@supportURL https://github.com/catppuccin/userstyles/issues?q=is%3Aopen+is%3Aissue+label%3Amullvad-leta
@description Soothing pastel theme for Mullvad Leta
@author Catppuccin
@license MIT

@preprocessor less
@var select lightFlavor "Light Flavor" ["latte:Latte*", "frappe:Frappé", "macchiato:Macchiato", "mocha:Mocha"]
@var select darkFlavor "Dark Flavor" ["latte:Latte", "frappe:Frappé", "macchiato:Macchiato", "mocha:Mocha*"]
@var select accentColor "Accent" ["rosewater:Rosewater", "flamingo:Flamingo", "pink:Pink", "mauve:Mauve*", "red:Red", "maroon:Maroon", "peach:Peach", "yellow:Yellow", "green:Green", "teal:Teal", "blue:Blue", "sapphire:Sapphire", "sky:Sky", "lavender:Lavender", "subtext0:Gray"]
==/UserStyle== */

@import "https://userstyles.catppuccin.com/lib/lib.less";

@-moz-document domain("leta.mullvad.net") {
  :root {
    @media (prefers-color-scheme: light) {
      #catppuccin(@lightFlavor);
    }
    @media (prefers-color-scheme: dark) {
      #catppuccin(@darkFlavor);
    }
  }

  #catppuccin(@flavor) {
    #lib.palette();
    #lib.defaults();

    &, svelte-css-wrapper > * {
      --blue: @base;
      --blue-dark: @mantle;
      --blue-link: @surface1;
      --blue-link--hover: @surface2;
      --text-link: @blue;

      --border-color: @accent;
      --bg-color-checked: @surface0;
      --bg-color-hover: @surface1;
      --divider-color: @surface1;
      --focus-outline-color: @accent;

      --color-text: @text;
      --color-icon: @subtext1;
      --chevron-color: @subtext1;
      --icons-color: @subtext1;
      --input-color: @subtext1;
      --placeholder-color: @subtext1;

      --border: 1px solid @surface0;
      --border-hover: 1px solid @surface2;
      --border-focused: 1px solid @surface2;
      --clear-select-focus-outline: 1px solid @accent;

      --background: @base;
      --list-background: @base;
      --disabled-background: @surface0;
      --disabled-border-color: @surface0;
      --form-control-disabled: @overlay0;

      --item-color: @subtext1;
      --item-hover-bg: @surface0;
      --item-hover-color: @subtext1;
      --item-is-active-bg: @surface1;
      --item-is-active-color: @text;
      --selected-item-color: @subtext1;

      --grey-dark: @surface1;
      --success: @green;
      --warning: @yellow;
      --danger: @red;
      --tag-danger-background: @red;
      --tag-danger-color: @base;
    }

    .results {
      /* favicons */
      .icon-wrapper {
        background-color: @mantle;
      }

      /* urls */
      cite {
        color: @subtext0;
      }
    }

    /* search query and engines */
    input[name="q"],
    .radio-group label {
      color: @text !important;
    }

    img[src="/mullvad-vpn-logo.svg"] {
      @svg: escape(
        '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 252 252" xml:space="preserve"><path d="M0 126c0 69.6 56.5 126 126 126s126-56.4 126-126S195.6 0 126 0 0 56.4 0 126" fill-rule="evenodd" clip-rule="evenodd" fill="transparent"/><path d="M23.9 96.6 16.8 111l9.6-13.4c0 .1-.6 19.3-.6 19.3l2.7-14.5c7.2 13.7 23.1 34.8 45.4 50.5 1.7 1.2 3.9 3.3 4.6 4.1 0 0 21.3 10.8 54.1-14.2.3-.2.7-.4 1-.6l.5.3 7.2 4.8c-2.5-.7-7.3-1.9-7.3-1.9-15.8 18.2-41.5 21.2-55.3 12-.6-.4-4 1-4.6 3-.4 1.1 0 2.3.5 3.2 2.8 5.2 7 4.7 5 10.8-1.4 3.3-3.4 6.5-5.6 9.5-4.6 6.2-11.8 11.7-11.1 15 32.6 40.2 106.1 34.6 134.1-1.3-.4-5.2-8.6-7.7-14.3-20.4 1.6.5 4 1.2 4 1.1s-6.8-11.1-7.1-12.2l4.4.3s-5.8-7.2-6-7.9l5.9-.8s-7.4-8.5-7.5-9.2l7.5 1.2-8.2-9.9h3.9l-4.6-6.7-37.3-14.7c-14.3-8.9-27-19.8-36.6-28.2l-19.3-9.4C63.3 79.4 46 79.9 35.4 82l6.8-11.6-9.9 11.8c-.6-.2-1.3-.4-1.3-.4l.7-15-3.3 14z" fill-rule="evenodd" clip-rule="evenodd" fill="@{peach}"/><path d="M28.4 80.8c-4.9-2.3-10.6 1-11.6 5.5-1.2 4.3 1.8 9.6 7.1 10.3 5-3.1 9.3-11.1 4.5-15.8" fill-rule="evenodd" clip-rule="evenodd" fill="@{rosewater}"/><path d="M101.2 69.9c-1.5-4.1-1.1-9.4 1-14.4 3-6.9 8.7-11.5 14.1-11.5 1.1 0 2.1.2 3.1.6 3.1-2.8 6.7-5.1 10.7-6.7 22-8.8 54.3 6.9 62.6 28.5 4 10.5 2.8 21.9-.6 32.4-2.8 8.6-13 21-9.2 30.3-1.5-.4-32.8-11-41.8-15.8-14.1-8.8-26.7-19.6-36.2-27.9l-.3-.3-32-15.2c-.4-.2-.8-.4-1.1-.6 4.4.2 21.9 2.3 29.7.6" fill-rule="evenodd" clip-rule="evenodd" fill="@{accent}"/><ellipse transform="rotate(-66.378 113.803 60.409)" cx="113.8" cy="60.4" rx="13.6" ry="8.1" fill="#f3f3f3"/><path d="M120.1 46.1c-5.3-2.3-12.4 2.2-15.9 10.1s-1.9 16.1 3.4 18.5c5.3 2.3 12.4-2.2 15.9-10.1s1.9-16.1-3.4-18.5m.5 17.3c-2.8 6.3-8.1 10.1-11.8 8.5-3.8-1.7-4.6-8.1-1.8-14.5 2.8-6.3 8.1-10.1 11.9-8.5 3.7 1.7 4.5 8.2 1.7 14.5" fill="transparent"/></svg>'
      );
      content: url("data:image/svg+xml,@{svg}");
    }

    a {
      color: @text;

      /* anchors */
      &[href^="#"]::before {
        color: @overlay2;
      }
    }

    /* tooltips */
    button:not([disabled])[aria-label] {
      &:focus::after, &:hover::after {
        color: @subtext1;
      }
    }

    footer a {
      color: @subtext1;
    }
  }
}

